// gpio_monitor.sv - generated by uvm_full_tb_generator.py, filled in:
//   publishes one item each time gpio_out_o changes (LED pattern).
class gpio_monitor extends uvm_monitor;
virtual gpio_if vif;
uvm_analysis_port #(gpio_item) ap;
`uvm_component_utils(gpio_monitor)
function new(string n,uvm_component p); super.new(n,p); ap=new("ap",this); endfunction

function void build_phase(uvm_phase phase);
  super.build_phase(phase);
  if (!uvm_config_db#(virtual gpio_if)::get(this, "", "gpio_vif", vif))
    `uvm_fatal("NOVIF", "gpio_vif not set in uvm_config_db")
endfunction

task run_phase(uvm_phase phase);
  logic [7:0] prev;
  wait (vif.rst_n === 1'b1);
  prev = vif.gpio_out_o;
  forever begin
    @(posedge vif.clk);
    if (vif.gpio_out_o !== prev) begin
      gpio_item tr = gpio_item::type_id::create("tr");
      tr.gpio_out_o = vif.gpio_out_o;
      `uvm_info("GPIO_MON", $sformatf("gpio_out_o %02h -> %02h", prev, tr.gpio_out_o), UVM_MEDIUM)
      prev = vif.gpio_out_o;
      ap.write(tr);
    end
  end
endtask
endclass
